package debugprint

import (
	"fmt"
	"io"
	"os"
	"reflect"
	"sort"
	"strconv"
	"strings"
)

// Config controls how values are rendered.
type Config struct {
	// Indent is the string written once per nesting level. Defaults to two spaces.
	Indent string
	// MaxDepth limits recursion depth. Zero means no limit.
	MaxDepth int
	// SortMapKeys sorts map keys to make output deterministic.
	SortMapKeys bool
	// PrintType includes the Go type name before composite values.
	PrintType bool
}

func NewDefaultConfig() *Config {
	return &Config{
		Indent:      "  ",
		MaxDepth:    0,
		SortMapKeys: true,
		PrintType:   true,
	}
}

type Printer struct {
	cfg *Config
}

func New(cfg *Config) *Printer {
	if cfg == nil {
		cfg = NewDefaultConfig()
	}
	c := *cfg
	if c.Indent == "" {
		c.Indent = "  "
	}
	return &Printer{cfg: &c}
}

func NewDefaultPrinter() *Printer { return New(nil) }

// Sdump returns the pretty-printed representation of the supplied values.
func (p *Printer) Sdump(a ...any) string {
	var b strings.Builder
	p.Fdump(&b, a...)
	return b.String()
}

func (p *Printer) Fdump(w io.Writer, a ...any) {
	st := &state{cfg: p.cfg, visited: map[uintptr]struct{}{}}
	for i, v := range a {
		if i > 0 {
			st.write("\n")
		}
		st.dump(reflect.ValueOf(v), 0)
		st.write("\n")
	}
	io.WriteString(w, st.b.String())
}
```

