func (s *state) dump(v reflect.Value, depth int) {
	if !v.IsValid() {
		s.write("<nil>")
		return
	}

	if s.cfg.MaxDepth > 0 && depth >= s.cfg.MaxDepth {
		s.write("...")
		return
